"""Test suite for requests.utils module."""

import codecs
import io
import os
import tempfile
import unittest
from collections import OrderedDict


class TestDictToSequence(unittest.TestCase):
    def test_dict_to_sequence_with_items(self):
        from requests.utils import dict_to_sequence
        d = {'a': 1, 'b': 2}
        result = dict_to_sequence(d)
        self.assertEqual(list(result), [('a', 1), ('b', 2)])

    def test_dict_to_sequence_with_list(self):
        from requests.utils import dict_to_sequence
        d = [('a', 1), ('b', 2)]
        result = dict_to_sequence(d)
        self.assertEqual(list(result), [('a', 1), ('b', 2)])


class TestSuperLen(unittest.TestCase):
    def test_super_len_with_list(self):
        from requests.utils import super_len
        data = [1, 2, 3, 4, 5]
        self.assertEqual(super_len(data), 5)

    def test_super_len_with_string(self):
        from requests.utils import super_len
        data = "hello"
        self.assertEqual(super_len(data), 5)

    def test_super_len_with_bytesio(self):
        from requests.utils import super_len
        data = io.BytesIO(b"hello")
        self.assertEqual(super_len(data), 5)

    def test_super_len_with_partial_read(self):
        from requests.utils import super_len
        data = io.BytesIO(b"hello world")
        data.read(5)  # Read "hello"
        self.assertEqual(super_len(data), 6)  # "world" remains

    def test_super_len_with_empty_file(self):
        from requests.utils import super_len
        data = io.BytesIO()
        self.assertEqual(super_len(data), 0)


