class TestExtractZippedPaths(unittest.TestCase):
    def test_extract_zipped_paths_existing_path(self):
        from requests.utils import extract_zipped_paths
        with tempfile.NamedTemporaryFile(delete=False) as f:
            temp_path = f.name
        try:
            result = extract_zipped_paths(temp_path)
            self.assertEqual(result, temp_path)
        finally:
            os.unlink(temp_path)

    def test_extract_zipped_paths_nonexistent(self):
        from requests.utils import extract_zipped_paths
        result = extract_zipped_paths("/nonexistent/path")
        self.assertEqual(result, "/nonexistent/path")


class TestAtomicOpen(unittest.TestCase):
    def test_atomic_open_writes_file(self):
        from requests.utils import atomic_open
        with tempfile.NamedTemporaryFile(delete=False) as f:
            temp_path = f.name
        try:
            with atomic_open(temp_path) as f:
                f.write(b"test content")
            with open(temp_path, 'rb') as f:
                content = f.read()
            self.assertEqual(content, b"test content")
        finally:
            if os.path.exists(temp_path):
                os.unlink(temp_path)


