class TestSetEnviron(unittest.TestCase):
    def test_set_environ_sets_and_restores(self):
        from requests.utils import set_environ
        # Ensure TEST_VAR doesn't exist for this test
        if 'TEST_VAR' in os.environ:
            del os.environ['TEST_VAR']
        with set_environ('TEST_VAR', 'test_value'):
            self.assertEqual(os.environ.get('TEST_VAR'), 'test_value')
        self.assertNotIn('TEST_VAR', os.environ)

