"""Test suite for pydantic serialization module."""
import pytest
from typing_extensions import Annotated


class TestPlainSerializer:
    """Tests for PlainSerializer class."""

    def test_plain_serializer_basic_creation(self):
        """Test basic creation of PlainSerializer instance."""
        from pydantic import PlainSerializer

        def serializer_func(value):
            return str(value)

        ps = PlainSerializer(func=serializer_func)
        assert ps.func == serializer_func
        assert ps.when_used == 'always'

    def test_plain_serializer_with_return_type(self):
        """Test PlainSerializer with explicit return_type."""
        from pydantic import PlainSerializer

        def serializer_func(value):
            return str(value)

        ps = PlainSerializer(func=serializer_func, return_type=str)
        assert ps.func == serializer_func
        assert ps.return_type == str

    def test_plain_serializer_with_when_used_always(self):
        """Test PlainSerializer with when_used='always'."""
        from pydantic import PlainSerializer

        def serializer_func(value):
            return str(value)

        ps = PlainSerializer(func=serializer_func, when_used='always')
        assert ps.when_used == 'always'

    def test_plain_serializer_with_when_used_unless_none(self):
        """Test PlainSerializer with when_used='unless-none'."""
        from pydantic import PlainSerializer

        def serializer_func(value):
            return str(value)

        ps = PlainSerializer(func=serializer_func, when_used='unless-none')
        assert ps.when_used == 'unless-none'

    def test_plain_serializer_with_when_used_json(self):
        """Test PlainSerializer with when_used='json'."""
        from pydantic import PlainSerializer

        def serializer_func(value):
            return str(value)

        ps = PlainSerializer(func=serializer_func, when_used='json')
        assert ps.when_used == 'json'

    def test_plain_serializer_with_when_used_json_unless_none(self):
        """Test PlainSerializer with when_used='json-unless-none'."""
        from pydantic import PlainSerializer

        def serializer_func(value):
            return str(value)

        ps = PlainSerializer(func=serializer_func, when_used='json-unless-none')
        assert ps.when_used == 'json-unless-none'

    def test_plain_serializer_frozen(self):
        """Test that PlainSerializer is frozen (immutable)."""
        from pydantic import PlainSerializer

        def serializer_func(value):
            return str(value)

        ps = PlainSerializer(func=serializer_func)
        # Try to modify - should raise an error since it's frozen
        with pytest.raises(Exception):
            ps.func = lambda x: x  # type: ignore

    def test_plain_serializer_dataclass_slots(self):
        """Test that PlainSerializer has __slots__ defined."""
        from pydantic import PlainSerializer

        def serializer_func(value):
            return str(value)

        ps = PlainSerializer(func=serializer_func)
        assert hasattr(ps, '__slots__') or '__dict__' not in dir(type(ps))


