class TestFieldSerializer:
    """Tests for field_serializer decorator."""

    def test_field_serializer_decorator_plain_mode(self):
        """Test field_serializer decorator in plain mode."""
        from pydantic import BaseModel, field_serializer

        class Model(BaseModel):
            name: str
            value: int

            @field_serializer('value')
            def serialize_value(self, v):
                return v * 2

        m = Model(name='test', value=5)
        result = m.model_dump()
        assert result['value'] == 10

    def test_field_serializer_decorator_with_fields(self):
        """Test field_serializer with multiple fields."""
        from pydantic import BaseModel, field_serializer

        class Model(BaseModel):
            name: str
            value: int
            count: int

            @field_serializer('value', 'count')
            def serialize_multi(self, v):
                return v * 2

        m = Model(name='test', value=5, count=3)
        result = m.model_dump()
        assert result['value'] == 10
        assert result['count'] == 6

    def test_field_serializer_decorator_when_used_json(self):
        """Test field_serializer with when_used='json'."""
        from pydantic import BaseModel, field_serializer

        class Model(BaseModel):
            name: str
            value: int

            @field_serializer('value', when_used='json')
            def serialize_value(self, v):
                return f"val_{v}"

        m = Model(name='test', value=5)
        json_result = m.model_dump_json()
        assert 'val_5' in json_result

    def test_field_serializer_decorator_when_used_always(self):
        """Test field_serializer with when_used='always'."""
        from pydantic import BaseModel, field_serializer

        class Model(BaseModel):
            name: str
            value: int

            @field_serializer('value', when_used='always')
            def serialize_value(self, v):
                return v * 10

        m = Model(name='test', value=5)
        result = m.model_dump()
        assert result['value'] == 50

    def test_field_serializer_decorator_check_fields(self):
        """Test field_serializer with check_fields=True."""
        from pydantic import BaseModel, field_serializer

        class Model(BaseModel):
            name: str
            value: int

            @field_serializer('value', check_fields=True)
            def serialize_value(self, v):
                return v * 2

        m = Model(name='test', value=5)
        result = m.model_dump()
