class TestPassContext:
    """Tests for pass_context decorator."""

    def test_pass_context_basic(self):
        """Test that pass_context passes the context object."""
        from click import get_current_context, Context as ClickContext

        @pass_context
        def callback(ctx, value):
            assert isinstance(ctx, ClickContext)
            return "has-context"

        # Create a command and invoke it properly
        cmd = command("test-cmd", params=[Argument(["value"])])(callback)

        # Invoke through context using proper invocation
        ctx = ClickContext(cmd)
        result = ctx.invoke(cmd.callback, "test_value")
        assert result == "has-context"

    def test_pass_context_with_args(self):
        """Test pass_context with additional arguments."""
        from click import Context as ClickContext

        @pass_context
        def callback(ctx, arg1, arg2):
            assert isinstance(ctx, ClickContext)
            return f"{arg1}-{arg2}"

        # Create a command and invoke it properly
        cmd = command("test-cmd", params=[Argument(["value"])])(callback)

        ctx = ClickContext(cmd)
        result = ctx.invoke(cmd.callback, "a", "b")
        assert result == "a-b"


