class TestMultipartPartDataclass:
    """Tests for MultipartPart dataclass."""

    def test_multipart_part_default_values(self):
        from dataclasses import dataclass, field
        from starlette.datastructures import UploadFile

        @dataclass
        class MultipartPart:
            content_disposition: typing.Optional[bytes] = None
            field_name: str = ""
            data: bytes = b""
            file: typing.Optional[UploadFile] = None
            item_headers: typing.List[typing.Tuple[bytes, bytes]] = field(default_factory=list)

        part = MultipartPart()
        assert part.content_disposition is None
        assert part.field_name == ""
        assert part.data == b""
        assert part.file is None
        assert part.item_headers == []

    def test_multipart_part_with_values(self):
        from dataclasses import dataclass, field
        from starlette.datastructures import UploadFile

        @dataclass
        class MultipartPart:
            content_disposition: typing.Optional[bytes] = None
            field_name: str = ""
            data: bytes = b""
            file: typing.Optional[UploadFile] = None
            item_headers: typing.List[typing.Tuple[bytes, bytes]] = field(default_factory=list)

        part = MultipartPart(
            content_disposition=b"form-data",
            field_name="test_field",
            data=b"test_data",
            item_headers=[(b"header1", b"value1")]
        )
        assert part.content_disposition == b"form-data"
        assert part.field_name == "test_field"
        assert part.data == b"test_data"
        assert part.file is None
        assert part.item_headers == [(b"header1", b"value1")]

    def test_multipart_part_immutable_fields(self):
        from dataclasses import dataclass, field
        from starlette.datastructures import UploadFile

        @dataclass
        class MultipartPart:
            content_disposition: typing.Optional[bytes] = None
            field_name: str = ""
            data: bytes = b""
            file: typing.Optional[UploadFile] = None
            item_headers: typing.List[typing.Tuple[bytes, bytes]] = field(default_factory=list)

        part = MultipartPart(field_name="original")
        assert part.field_name == "original"
        # Dataclass fields are mutable, but we can verify the initial value
        assert hasattr(part, 'field_name')


class TestUserSafeDecode:
    """Tests for _user_safe_decode function."""

    def test_user_safe_decode_ascii(self):
        def _user_safe_decode(src: bytes, codec: str) -> str:
            try:
                return src.decode(codec)
            except (UnicodeDecodeError, LookupError):
                return src.decode("latin-1")

        result = _user_safe_decode(b"hello", "utf-8")
        assert result == "hello"

