def test_wrap_text_preserve_paragraphs():
    """Test wrap_text with paragraph preservation."""
    from click._textwrap import TextWrapper

    def wrap_text(text, width=78, initial_indent="", subsequent_indent="", preserve_paragraphs=False):
        text = text.expandtabs()
        wrapper = TextWrapper(
            width,
            initial_indent=initial_indent,
            subsequent_indent=subsequent_indent,
            replace_whitespace=False,
        )
        if not preserve_paragraphs:
            return wrapper.fill(text)
        p = []
        buf = []
        indent = None
        def _flush_par():
            if not buf:
                return
            if buf[0].strip() == "\b":
                p.append((indent or 0, True, "\n".join(buf[1:])))
            else:
                p.append((indent or 0, False, " ".join(buf)))
            del buf[:]
        for line in text.splitlines():
            if not line:
                _flush_par()
                indent = None
            else:
                if indent is None:
                    orig_len = term_len(line)
                    line = line.lstrip()
                    indent = orig_len - term_len(line)
                buf.append(line)
        _flush_par()
        rv = []
        for ind, raw, txt in p:
            with wrapper.extra_indent(" " * ind):
                if raw:
                    rv.append(wrapper.indent_only(txt))
                else:
                    rv.append(wrapper.fill(txt))
        return "\n\n".join(rv)

    result = wrap_text("Para1\n\nPara2", width=20, preserve_paragraphs=True)
    assert "Para1" in result or "Para2" in result


